"""Text-to-SQL harness: draft query, execute it, probe it locally, and spend the
second policy call on a repair turn when the draft errors, returns no rows, looks
cut off, or when local probes show a likely semantic defect (join fan-out that
duplicates entity rows / inflates aggregates, or a filter literal that does not
exist in the column it is compared against).

Contract (fixed): solve(task, env) -> {"sql": str}
"""

import re

SQL_BLOCK = re.compile(r"```(?:sql|sqlite)?\s*(.*?)```", re.S | re.I)
START_KW = re.compile(r"^\s*(WITH|SELECT)\b", re.I)
EQ_LIT = re.compile(
    r"([A-Za-z_][\w.]*)\s*(=|!=|<>|\bLIKE\b)\s*'([^']*)'", re.I
)


def extract_sql(text):
    text = text or ""
    blocks = [b.strip() for b in SQL_BLOCK.findall(text) if b.strip()]
    if blocks:
        return blocks[-1].rstrip(";").strip()
    # Unclosed code fence (truncated generation): take what follows the fence.
    m = re.search(r"```(?:sql|sqlite)?\s*(.*)$", text, re.S | re.I)
    if m and START_KW.match(m.group(1)):
        return m.group(1).strip().rstrip(";").strip()
    # Bare SQL somewhere in the reply.
    m = re.search(r"(?:^|\n)\s*(WITH|SELECT)\b", text, re.I)
    if m:
        return text[m.start():].strip().rstrip(";").strip()
    return text.strip().rstrip(";").strip()


def looks_truncated(sql):
    if not sql:
        return True
    if sql.count("(") != sql.count(")"):
        return True
    if sql.count("'") % 2 == 1 or sql.count('"') % 2 == 1:
        return True
    if re.search(r"\b(SELECT|FROM|WHERE|AND|OR|BY|ON|JOIN|HAVING|LIMIT|AS|IN|LIKE|=|<|>|,)\s*$", sql, re.I):
        return True
    return False


def build_user(task, env):
    user = (
        f"Database: {task['db_id']}\n\nSchema:\n{env.schema(task['db_id'])}"
    )
    desc = ""
    try:
        desc = env.descriptions(task["db_id"]) or ""
    except Exception:
        desc = ""
    if desc.strip():
        user += f"\n\nColumn descriptions:\n{desc.strip()[:4000]}"
    user += f"\n\nQuestion: {task['question']}"
    if task.get("hint"):
        user += f"\nHint: {task['hint']}"
    return user


# ---------------------------------------------------------------- local probes

def _run(env, sql, max_rows=20):
    try:
        return env.execute(sql, max_rows=max_rows)
    except Exception:
        return None


def _ok(r):
    return r is not None and r.get("ok")


def dedup_variant(sql):
    """SELECT DISTINCT <same projection>, used only as a diagnostic."""
    if not re.match(r"^\s*SELECT\s+(?!DISTINCT\b)", sql, re.I):
        return None
    if re.search(r"\bGROUP\s+BY\b", sql, re.I):
        return None
    return re.sub(r"^(\s*SELECT\s+)", r"\1DISTINCT ", sql, count=1, flags=re.I)


def fanout_evidence(env, sql, res):
    """Detect one-to-many join fan-out: same query with DISTINCT returns fewer
    rows. That means entity rows are repeated (list questions) or an aggregate
    is computed over duplicated rows."""
    if not _ok(res) or res.get("n_rows", 0) <= 1:
        return None
    if not re.search(r"\bJOIN\b", sql, re.I):
        return None
    alt = dedup_variant(sql)
    if not alt:
        return None
    r2 = _run(env, alt, max_rows=20)
    if not _ok(r2):
        return None
    n1, n2 = res.get("n_rows", 0), r2.get("n_rows", 0)
    if n2 >= n1 or n2 == 0:
        return None
    agg = re.search(r"\b(SUM|AVG|COUNT|TOTAL)\s*\(", sql, re.I)
    lines = [
        f"Diagnostic: your query returned {n1} rows, but the identical query with SELECT DISTINCT "
        f"returned {n2} rows. A one-to-many JOIN is therefore repeating rows."
    ]
    if agg:
        lines.append(
            "Because you aggregate, SUM/COUNT/AVG are computed over duplicated rows and are inflated. "
            "Filter with a semi-join instead: WHERE <key> IN (SELECT <key> FROM <child table> WHERE ...) "
            "or EXISTS(...), and aggregate over the main entity table only."
        )
    else:
        lines.append(
            "If the question lists entities, each entity should normally appear once (use DISTINCT, or a "
            "semi-join WHERE <key> IN (SELECT ...)). Only keep duplicates if the question really asks for "
            "one row per matching child record."
        )
    return "\n".join(lines)


def literal_evidence(env, sql):
    """For each column compared to a string literal, check whether that value
    actually occurs in the column; if not, show the stored values."""
    if "'" not in sql:
        return None
    seen = set()
    notes = []
    for m in EQ_LIT.finditer(sql):
        col, op, val = m.group(1), m.group(2), m.group(3)
        if not val or len(val) > 60:
            continue
        bare = col.split(".")[-1]
        key = (bare.lower(), val.lower())
        if key in seen:
            continue
        seen.add(key)
        if len(seen) > 3:
            break
        esc = val.replace("'", "''")
        hit = _run(env, f"SELECT 1 FROM (SELECT {bare} AS v FROM {bare}) WHERE 1=0", max_rows=1)
        # Direct existence check on the qualified column via a subquery over the
        # whole statement's tables is not possible generically; use the draft's
        # own FROM clause by wrapping it is unsafe, so probe with a simple
        # table-less check first and fall back to scanning the draft's tables.
        found = None
        for tbl in re.findall(r"\b(?:FROM|JOIN)\s+([A-Za-z_]\w*)", sql, re.I):
            r = _run(
                env,
                f"SELECT COUNT(*) FROM {tbl} WHERE CAST({bare} AS TEXT) = '{esc}'",
                max_rows=1,
            )
            if _ok(r) and r.get("rows"):
                try:
                    found = int(r["rows"][0][0]) > 0
                except Exception:
                    found = None
                if found:
                    break
        if found:
            continue
        vals = None
        for tbl in re.findall(r"\b(?:FROM|JOIN)\s+([A-Za-z_]\w*)", sql, re.I):
            r = _run(env, f"SELECT DISTINCT {bare} FROM {tbl} LIMIT 20", max_rows=20)
            if _ok(r):
                vals = [row[0] for row in r.get("rows", [])]
                break
        if vals is None:
            continue
        shown = ", ".join(repr(v) for v in vals[:20])
        notes.append(
            f"Diagnostic: no row in the database has {bare} = '{val}' (comparison used: {op}). "
            f"Actual stored values of {bare} include: {shown}. "
            "Either the literal is spelled/cased differently, or you are filtering the wrong column."
        )
    if not notes:
        return None
    return "\n".join(notes)


def repair_message(sql, res, truncated, extra):
    lines = ["Your previous draft was:", "```sql", sql, "```"]
    if truncated:
        lines.append("It appears incomplete or malformed (cut off mid-statement). Rewrite it as one short, complete query.")
    if res is None:
        lines.append("It could not be executed.")
    elif not res.get("ok"):
        lines.append(f"Execution FAILED with error: {res.get('error')}")
        lines.append("Fix the syntax or the table/column names (use only names present in the schema).")
    elif res.get("n_rows", 0) == 0:
        lines.append("It executed successfully but returned 0 rows.")
        lines.append(
            "A filter value, a join, or the choice of filtered column is probably wrong. "
            "Common causes: string literals that do not exactly match stored values (case, spacing, "
            "abbreviations, suffixes), matching a name-like column when the question refers to a "
            "category/official-flag column, or an over-restrictive combination of conditions. "
            "An empty answer is possible but rare; verify before keeping it."
        )
    else:
        lines.append(f"It returned {res.get('n_rows')} rows; columns: {res.get('columns')}.")
        lines.append("Re-check that it answers the question exactly (right columns, right comparison semantics).")
    if extra:
        lines.append("")
        lines.extend(extra)
    lines.append(
        "Reply with ONLY the corrected final query in a single ```sql code block. "
        "Keep it minimal: select exactly the columns asked for, nothing extra."
    )
    return "\n".join(lines)


def solve(task, env):
    max_tokens = env.config.get("max_tokens", 800)
    messages = [
        {"role": "system", "content": env.prompt("system_prompt.md")},
        {"role": "user", "content": build_user(task, env)},
    ]
    reply = env.chat(messages, max_tokens=max_tokens)
    sql = extract_sql(reply)

    truncated = looks_truncated(sql)
    res = _run(env, sql)

    extra = []
    if not truncated and _ok(res):
        ev = fanout_evidence(env, sql, res)
        if ev:
            extra.append(ev)
        ev = literal_evidence(env, sql)
        if ev:
            extra.append(ev)

    need_repair = (
        truncated
        or res is None
        not_ok := False
    ) if False else (
        truncated or not _ok(res) or res.get("n_rows", 0) == 0 or bool(extra)
    )
    if not need_repair:
        return {"sql": sql}

    messages.append({"role": "assistant", "content": reply})
    messages.append({"role": "user", "content": repair_message(sql, res, truncated, extra)})
    try:
        reply2 = env.chat(messages, max_tokens=max_tokens)
    except Exception:
        return {"sql": sql}
    sql2 = extract_sql(reply2)
    if not sql2:
        return {"sql": sql}

    res2 = _run(env, sql2)

    def usable(r):
        return _ok(r) and r.get("n_rows", 0) > 0

    if usable(res2) or not usable(res):
        if looks_truncated(sql2) and not truncated:
            return {"sql": sql}
        return {"sql": sql2}
    return {"sql": sql}

